// ══════════════════════════════════════════════════
// ÉTAPE 3 : Garde-fou avant restart
// Règles heuristiques déterministes — PAS de l'IA
//
// Conditions STRICTES pour déclencher un restart :
//   1. status === 'DOWN' ou 'DEGRADED'
//   2. httpOK === false (service KO confirmé HTTP)
//   3. Type non dans la liste des exclus
// ══════════════════════════════════════════════════

const data       = $input.first().json;
const sshTargets = data.sshTargets || [];

// Types d'équipements jamais redémarrés automatiquement
// (pas d'accès SSH ou redémarrage trop risqué)
const TYPES_EXCLUS = [
  'Routeur', 'Routeur WiFi', 'Mikrotik',
  'Access Point', 'Switch',
  'DNS Google', 'DNS Cloudflare',
  'Imprimante', 'Telephone', 'Inconnu'
];

// ── Séparer les cibles en catégories ──────────────
const exclusParType  = sshTargets.filter(d => TYPES_EXCLUS.includes(d.type));
const httpEncoreOK   = sshTargets.filter(d => !TYPES_EXCLUS.includes(d.type) && d.httpOK !== false);
const eligibles      = sshTargets.filter(d =>
  (d.status === 'DOWN' || d.status === 'DEGRADED') &&
  d.httpOK === false &&
  !TYPES_EXCLUS.includes(d.type)
);

// ── Construire la commande SSH ─────────────────────
const sshCommand = eligibles.length === 0
  ? null
  : eligibles
      .map(d => `echo '=== [${d.name}] ===' && ${d.sshCmd} 2>&1`)
      .join(' && echo "---" && ');

// ── Message d'explication précis ──────────────────
let sshSkippedReason = null;
if (eligibles.length === 0) {
  const raisons = [];

  if (exclusParType.length > 0) {
    const noms = exclusParType.map(d => `${d.name} (${d.type})`).join(', ');
    raisons.push(`${noms} → équipement non redémarrable à distance`);
  }

  if (httpEncoreOK.length > 0) {
    const noms = httpEncoreOK.map(d => d.name).join(', ');
    raisons.push(`${noms} → service HTTP encore accessible, pas de restart nécessaire`);
  }

  sshSkippedReason = raisons.length > 0
    ? raisons.join(' | ')
    : 'Aucun service éligible au redémarrage automatique';
}

return [{
  json: {
    ...data,
    sshCommand,
    sshEligibles:     eligibles.length,
    eligibleDevices:  eligibles.map(d => d.name),
    exclusParType:    exclusParType.map(d => `${d.name} (${d.type})`),
    sshSkippedReason
  }
}];

// ══════════════════════════════════════════════════
// ÉTAPE 1 : Analyse + Service Map
// ══════════════════════════════════════════════════

const serviceMap = {

  // ── ROUTEURS ──────────────────────────────────────
  '192.168.1.1': { type: 'Routeur WiFi', critical: true, sshCmd: null },

  // ── SWITCHES ──────────────────────────────────────
  '192.168.1.2': { type: 'Switch',       critical: true, sshCmd: null },

  // ── DNS PUBLICS ───────────────────────────────────
  '8.8.8.8':       { type: 'DNS Google',     critical: true, sshCmd: null },
  '1.1.1.1':       { type: 'DNS Cloudflare', critical: true, sshCmd: null },

  // ── SERVEUR LINUX ─────────────────────────────────
  // Ordre : diagnostic système → restart services
  '192.168.1.50': {
    type: 'Serveur Linux',
    critical: false,
    sshCmd: [

      // 1. Diagnostic disque et RAM avant toute action
      "DISK=$(df -h / | awk 'NR==2{print $5}')",
      "RAM=$(free -m | awk 'NR==2{printf \"%s/%s Mo\", $3,$2}')",
      "echo \"DIAG_DISK:$DISK DIAG_RAM:$RAM\"",

      // Alerte si disque > 85%
      "DISK_PCT=$(df / | awk 'NR==2{gsub(/%/,\"\",$5); print $5}')",
      "if [ \"$DISK_PCT\" -gt 85 ]; then echo \"WARN_DISK: Disque plein a ${DISK_PCT}% — cause probable du crash\"; fi",

      "echo '--- Remediation services ---'",

      // Apache2
      "APACHE_STATUS='absent'",
      "if systemctl list-unit-files 2>/dev/null | grep -q '^apache2.service'; then",
      "  if ! systemctl is-active --quiet apache2; then",
      "    sudo systemctl restart apache2 2>&1",
      "    if systemctl is-active --quiet apache2; then",
      "      APACHE_STATUS='redemarre_OK';",
      "      echo 'OK: apache2 redemarre avec succes';",
      "    else",
      "      APACHE_STATUS='echec';",
      "      echo 'ERREUR: apache2 restart echoue';",
      "    fi",
      "  else",
      "    APACHE_STATUS='deja_actif';",
      "    echo 'INFO: apache2 deja actif';",
      "  fi",
      "fi",

      // Nginx
      "NGINX_STATUS='absent'",
      "if systemctl list-unit-files 2>/dev/null | grep -q '^nginx.service'; then",
      "  if ! systemctl is-active --quiet nginx; then",
      "    sudo systemctl restart nginx 2>&1",
      "    if systemctl is-active --quiet nginx; then",
      "      NGINX_STATUS='redemarre_OK';",
      "      echo 'OK: nginx redemarre avec succes';",
      "    else",
      "      NGINX_STATUS='echec';",
      "      echo 'ERREUR: nginx restart echoue';",
      "    fi",
      "  else",
      "    NGINX_STATUS='deja_actif';",
      "    echo 'INFO: nginx deja actif';",
      "  fi",
      "fi",

      // MySQL
      "MYSQL_STATUS='absent'",
      "if systemctl list-unit-files 2>/dev/null | grep -q '^mysql.service'; then",
      "  if ! systemctl is-active --quiet mysql; then",
      "    sudo systemctl restart mysql 2>&1",
      "    if systemctl is-active --quiet mysql; then",
      "      MYSQL_STATUS='redemarre_OK';",
      "      echo 'OK: mysql redemarre avec succes';",
      "    else",
      "      MYSQL_STATUS='echec';",
      "      echo 'ERREUR: mysql restart echoue';",
      "    fi",
      "  else",
      "    MYSQL_STATUS='deja_actif';",
      "    echo 'INFO: mysql deja actif';",
      "  fi",
      "fi",

      // Bilan final parseable par n8n
      "echo \"BILAN_APACHE:$APACHE_STATUS|BILAN_NGINX:$NGINX_STATUS|BILAN_MYSQL:$MYSQL_STATUS\""

    ].join("\n")
  }
};

// ── Traitement données PowerShell ─────────────────
const data    = $input.first().json.body ?? $input.first().json;
const devices = Array.isArray(data.devices) ? data.devices : [];

const enriched = devices.map(d => ({
  ...d,
  ...(serviceMap[d.ip] || { type: 'Inconnu', critical: false, sshCmd: null })
}));

const down     = enriched.filter(d => d.status === 'DOWN');
const up       = enriched.filter(d => d.status === 'UP');
const degraded = enriched.filter(d => d.status === 'DEGRADED');
const masked   = enriched.filter(d => d.status === 'MASKED');
const critical = down.filter(d => d.critical);

// Traduction statut en français
const tradStatut = { UP: 'En ligne', DOWN: 'Hors service', DEGRADED: 'Dégradé', MASKED: 'Masqué' };
const tradSev    = { OK: '✅ Normal', WARNING: '⚠️ Alerte', DEGRADED: '🟡 Dégradé', CRITICAL: '🔴 Critique', UNKNOWN: '❓ Inconnu' };

return [{
  json: {
    timestamp:     data.timestamp     || new Date().toISOString(),
    severity:      data.severity      || 'UNKNOWN',
    severityFR:    tradSev[data.severity] || data.severity,
    totalDevices:  enriched.length,
    upCount:       up.length,
    downCount:     down.length,
    degradedCount: degraded.length,
    maskedCount:   masked.length,
    criticalCount: critical.length,
    highRiskCount: data.highRiskCount || 0,
    downDevices:   down,
    allDevices:    enriched,
    tradStatut
  }
}];

const staticData = $getWorkflowStaticData('global');
const data       = $input.first().json;

if (!staticData.failureCounts)  staticData.failureCounts  = {};
if (!staticData.totalIncidents) staticData.totalIncidents = 0;

const allDevices      = data.allDevices || [];
const downDevices     = allDevices.filter(d => d.status === 'DOWN');
const degradedDevices = allDevices.filter(d => d.status === 'DEGRADED' && d.httpOK === false);
const problemDevices  = [...downDevices, ...degradedDevices];

for (const d of problemDevices) {
  staticData.failureCounts[d.ip] = (staticData.failureCounts[d.ip] || 0) + 1;
}
for (const d of allDevices) {
  if (d.status === 'UP') staticData.failureCounts[d.ip] = 0;
}

const confirmedDown = problemDevices
  .map(d => ({ ...d, consecutiveFailures: staticData.failureCounts[d.ip] || 1 }))
  .filter(d => d.consecutiveFailures >= 2);

const sshTargets = confirmedDown.filter(d => d.sshCmd !== null && d.sshCmd !== undefined);

if (confirmedDown.length > 0) staticData.totalIncidents += 1;

return [{
  json: {
    ...data,
    confirmedDown,
    confirmedDownCount: confirmedDown.length,
    sshTargets,
    sshRequired:    sshTargets.length > 0,
    confirmed:      confirmedDown.length > 0,
    totalIncidents: staticData.totalIncidents,
    failureCounts:  { ...staticData.failureCounts }
  }
}];

const sshOutput = $input.first().json;
const data      = $('Code - Garde-fou & commande SSH ciblée').first().json;
const confirmed = data.confirmedDown || [];

const deviceList = confirmed.length > 0
  ? confirmed.map(d => `${d.name}(${d.ip})[${d.type||'N/A'}]x${d.consecutiveFailures||1}`).join(' | ')
  : 'Aucun device confirme';

const sshInfo = data.sshEligibles > 0
  ? `SSH_OK:${(data.eligibleDevices||[]).join(',')} — ${sshOutput.stdout||''}`
  : `SSH_SKIP:${data.sshSkippedReason||'N/A'}`;

const logLine = [
  data.timestamp                || new Date().toISOString(),
  `SEV:${data.severity          || 'N/A'}`,
  `INCIDENT#${data.totalIncidents    || 0}`,
  `DOWN_CONFIRMES:${data.confirmedDownCount || 0}`,
  deviceList,
  sshInfo
].join(' || ');

return [{ json: { ...data, sshResult: sshOutput.stdout, logLine } }];

const data    = $input.first().json;
const logLine = data.logLine || 'no-log';
console.log('NET-MONITOR LOG:', logLine);
return $input.all();

const staticData = $getWorkflowStaticData('global');

// on sauvegarde TOUT le résultat enrichi
staticData.lastStatus = $input.first().json;

return $input.all();

const staticData = $getWorkflowStaticData('global');

return [{
  json: staticData.lastStatus || {
    message: "Pas encore de données"
  }
}];
